{"code": "const { readFileSync } = await import('node:fs');
const raw = readFileSync('/Users/oyamahappa/Documents/Agent/DSH/vibe-coding-ppt/content/03-codex.json', 'utf8');
const obj = JSON.parse(raw);
const valid = new Set(['cover','section','bullets','cards','table','steps','quote','end']);
const bad = obj.slides.map((s:any,i:number)=> valid.has(s.layout)?null:`${i}:${s.layout}`).filter(Boolean);
const tables = obj.slides.filter((s:any)=>s.layout==='table').map((s:any)=>({t:s.title, cols:s.headers.length, totalRows:s.rows.length+1}));
return JSON.stringify({ deck: obj.deck, slides: obj.slides.length, bytes: Buffer.byteLength(raw), badLayouts: bad, tables }, null, 2);", "description": "Validate written JSON structure"}
